const std = @import("std");
const nccl = @import("nccl_bindings.zig");

fn constOpaquePtrFrom(value: anytype) !*const anyopaque {
    const T = @TypeOf(value);
    return switch (@typeInfo(T)) {
        .pointer => |ptr_info| switch (ptr_info.size) {
            .one => @ptrCast(value),
            .slice => blk: {
                if (value.len == 0) {
                    return error.EmptyBuffer;
                }
                break :blk @ptrCast(&value[0]);
            },
            .many, .c => @compileError("constOpaquePtrFrom: expected single pointer or slice, got unbounded pointer type " ++ @typeName(T)),
        },
        else => @compileError("constOpaquePtrFrom: expected pointer or slice, got " ++ @typeName(T)),
    };
}

fn opaquePtrFrom(value: anytype) !*anyopaque {
    const T = @TypeOf(value);
    return switch (@typeInfo(T)) {
        .pointer => |ptr_info| switch (ptr_info.size) {
            .one => blk: {
                if (ptr_info.is_const) {
                    @compileError("opaquePtrFrom: expected mutable pointer, got " ++ @typeName(T));
                }
                break :blk @ptrCast(value);
            },
            .slice => blk: {
                if (ptr_info.is_const) {
                    @compileError("opaquePtrFrom: expected mutable slice, got " ++ @typeName(T));
                }
                if (value.len == 0) {
                    return error.EmptyBuffer;
                }
                break :blk @ptrCast(&value[0]);
            },
            .many, .c => @compileError("opaquePtrFrom: expected single pointer or slice, got unbounded pointer type " ++ @typeName(T)),
        },
        else => @compileError("opaquePtrFrom: expected pointer or slice, got " ++ @typeName(T)),
    };
}

fn checkCuda(err: nccl.CudaError, comptime tag: []const u8, fail_error: anyerror) !void {
    if (err != .cudaSuccess) {
        const err_str = nccl.cudaGetErrorString(err);
        std.debug.print("CUDA error [{s}]: {s}\n", .{ tag, err_str });
        return fail_error;
    }
}

fn checkNccl(err: nccl.ncclResult_t, comptime tag: []const u8, fail_error: anyerror) !void {
    if (err != .ncclSuccess) {
        const err_str = nccl.ncclGetErrorString(err);
        std.debug.print("NCCL error [{s}]: {s}\n", .{ tag, err_str });
        return fail_error;
    }
}

fn logCudaFailure(err: nccl.CudaError, comptime tag: []const u8) void {
    if (err != .cudaSuccess) {
        const err_str = nccl.cudaGetErrorString(err);
        std.debug.print("CUDA cleanup error [{s}]: {s}\n", .{ tag, err_str });
    }
}

fn logNcclFailure(err: nccl.ncclResult_t, comptime tag: []const u8) void {
    if (err != .ncclSuccess) {
        const err_str = nccl.ncclGetErrorString(err);
        std.debug.print("NCCL cleanup error [{s}]: {s}\n", .{ tag, err_str });
    }
}

pub const GPUCoordinator = struct {
    world_size: usize,
    rank: usize,
    device_id: i32,
    nccl_comm: ?*nccl.ncclComm,
    cuda_stream: ?*anyopaque,

    pub fn init(world_size: usize, rank: usize, local_rank: usize, nccl_id: nccl.ncclUniqueId) !GPUCoordinator {
        if (world_size == 0) {
            return error.InvalidWorldSize;
        }
        if (rank >= world_size) {
            return error.InvalidRank;
        }
        if (world_size > @as(usize, @intCast(std.math.maxInt(c_int)))) {
            return error.WorldSizeTooLarge;
        }
        if (rank > @as(usize, @intCast(std.math.maxInt(c_int)))) {
            return error.RankTooLarge;
        }

        var device_count: c_int = 0;
        try checkCuda(nccl.cudaGetDeviceCount(&device_count), "cudaGetDeviceCount", error.CudaGetDeviceCountFailed);
        if (device_count <= 0) {
            return error.InsufficientGPUs;
        }

        const local_device_count: usize = @intCast(device_count);
        if (local_rank >= local_device_count) {
            return error.LocalRankExceedsDeviceCount;
        }
        const device_id_usize: usize = local_rank;
        if (device_id_usize > @as(usize, @intCast(std.math.maxInt(i32)))) {
            return error.DeviceIdOutOfRange;
        }
        const device_id: i32 = @intCast(device_id_usize);

        try checkCuda(nccl.cudaSetDevice(device_id), "cudaSetDevice", error.CudaSetDeviceFailed);

        // Single-GPU mode: skip ncclCommInitRank entirely when world_size==1.
        // ncclCommInitRank probes the network stack (InfiniBand, shared memory,
        // etc.) even for a single rank, producing warnings and wasting ~0.5 s.
        // For world_size>1 we still initialize NCCL normally.
        var nccl_comm_opt: ?*nccl.ncclComm = null;
        if (world_size > 1) {
            var nccl_comm_local: *nccl.ncclComm = undefined;
            try checkNccl(
                nccl.ncclCommInitRank(&nccl_comm_local, @intCast(world_size), nccl_id, @intCast(rank)),
                "ncclCommInitRank",
                error.NCCLCommInitFailed,
            );
            errdefer logNcclFailure(nccl.ncclCommDestroy(nccl_comm_local), "ncclCommDestroy(init rollback)");
            nccl_comm_opt = nccl_comm_local;
        } else {
            std.debug.print("[GPUCoordinator] world_size=1: single-GPU mode; skipping ncclCommInitRank\n", .{});
        }

        var cuda_stream_local: *anyopaque = undefined;
        try checkCuda(nccl.cudaStreamCreate(&cuda_stream_local), "cudaStreamCreate", error.CudaStreamCreateFailed);
        errdefer logCudaFailure(nccl.cudaStreamDestroy(cuda_stream_local), "cudaStreamDestroy(init rollback)");

        return GPUCoordinator{
            .world_size = world_size,
            .rank = rank,
            .device_id = device_id,
            .nccl_comm = nccl_comm_opt,
            .cuda_stream = cuda_stream_local,
        };
    }

    pub fn deinit(self: *GPUCoordinator) void {
        logCudaFailure(nccl.cudaSetDevice(self.device_id), "cudaSetDevice(deinit)");

        if (self.cuda_stream) |stream| {
            logCudaFailure(nccl.cudaStreamSynchronize(stream), "cudaStreamSynchronize(deinit)");
        }

        if (self.nccl_comm) |comm| {
            logNcclFailure(nccl.ncclCommFinalize(comm), "ncclCommFinalize");
            logNcclFailure(nccl.ncclCommDestroy(comm), "ncclCommDestroy");
            self.nccl_comm = null;
        }

        if (self.cuda_stream) |stream| {
            logCudaFailure(nccl.cudaStreamDestroy(stream), "cudaStreamDestroy");
            self.cuda_stream = null;
        }
    }

    fn setDevice(self: *GPUCoordinator) !void {
        try checkCuda(nccl.cudaSetDevice(self.device_id), "cudaSetDevice", error.CudaSetDeviceFailed);
    }

    fn requireComm(self: *GPUCoordinator) !*nccl.ncclComm {
        return self.nccl_comm orelse return error.CoordinatorNotInitialized;
    }

    fn requireStream(self: *GPUCoordinator) !*anyopaque {
        return self.cuda_stream orelse return error.CoordinatorNotInitialized;
    }

    pub fn allocDeviceMemory(self: *GPUCoordinator, size: usize) !*anyopaque {
        if (size == 0) {
            return error.InvalidAllocationSize;
        }

        try self.setDevice();

        var dev_ptr: ?*anyopaque = null;
        try checkCuda(nccl.cudaMalloc(&dev_ptr, size), "cudaMalloc", error.CudaMallocFailed);
        return dev_ptr orelse return error.CudaMallocFailed;
    }

    pub fn freeDeviceMemory(self: *GPUCoordinator, ptr: ?*anyopaque) void {
        self.setDevice() catch |err| {
            std.debug.print("CUDA cleanup error [cudaSetDevice(freeDeviceMemory)]: {}\n", .{err});
            return;
        };
        if (ptr) |p| {
            logCudaFailure(nccl.cudaFree(p), "cudaFree");
        }
    }

    fn doMemcpy(
        self: *GPUCoordinator,
        dst_ptr: *anyopaque,
        src_ptr: *const anyopaque,
        size: usize,
        kind: c_int,
        comptime tag: []const u8,
    ) !void {
        if (size == 0) {
            return;
        }

        _ = try self.requireStream();
        try self.setDevice();
        try checkCuda(nccl.cudaMemcpy(dst_ptr, src_ptr, size, kind), tag, error.CudaMemcpyFailed);
    }

    pub fn copyHostToDevice(self: *GPUCoordinator, dst: anytype, src: anytype, size: usize) !void {
        if (size == 0) {
            return;
        }

        const dst_ptr = try opaquePtrFrom(dst);
        const src_ptr = try constOpaquePtrFrom(src);
        try self.doMemcpy(dst_ptr, src_ptr, size, nccl.cudaMemcpyKind.cudaMemcpyHostToDevice, "cudaMemcpyHostToDevice");
    }

    pub fn copyDeviceToHost(self: *GPUCoordinator, dst: anytype, src: anytype, size: usize) !void {
        if (size == 0) {
            return;
        }

        const dst_ptr = try opaquePtrFrom(dst);
        const src_ptr = try constOpaquePtrFrom(src);
        try self.doMemcpy(dst_ptr, src_ptr, size, nccl.cudaMemcpyKind.cudaMemcpyDeviceToHost, "cudaMemcpyDeviceToHost");
    }

    fn doAllReduce(
        self: *GPUCoordinator,
        send_buf: *const anyopaque,
        recv_buf: *anyopaque,
        count: usize,
        dtype: nccl.ncclDataType_t,
        op: nccl.ncclRedOp_t,
        comptime tag: []const u8,
    ) !void {
        if (count == 0) {
            return;
        }
        // For world_size==1 the local value is already the global value.
        // Copy send→recv in case the caller passed distinct buffers, then return.
        if (self.world_size == 1) {
            if (send_buf != recv_buf) {
                const elem_bytes: usize = switch (dtype) {
                    .ncclFloat16 => 2,
                    .ncclFloat32 => 4,
                    else => 4,
                };
                try checkCuda(
                    nccl.cudaMemcpy(recv_buf, send_buf, try std.math.mul(usize, count, elem_bytes), nccl.cudaMemcpyKind.cudaMemcpyDeviceToDevice),
                    tag ++ "(single-rank-copy)",
                    error.CudaMemcpyFailed,
                );
            }
            return;
        }

        const comm = try self.requireComm();
        const stream = try self.requireStream();
        try self.setDevice();

        try checkNccl(
            nccl.ncclAllReduce(send_buf, recv_buf, count, dtype, op, comm, stream),
            tag,
            error.NCCLAllReduceFailed,
        );
    }

    pub fn allReduceFloat32(self: *GPUCoordinator, send_buf: *const anyopaque, recv_buf: *anyopaque, count: usize) !void {
        try self.doAllReduce(send_buf, recv_buf, count, .ncclFloat32, .ncclSum, "ncclAllReduceFloat32Sum");
    }

    pub fn allReduceFloat32Max(self: *GPUCoordinator, send_buf: *const anyopaque, recv_buf: *anyopaque, count: usize) !void {
        try self.doAllReduce(send_buf, recv_buf, count, .ncclFloat32, .ncclMax, "ncclAllReduceFloat32Max");
    }

    pub fn synchronize(self: *GPUCoordinator) !void {
        const stream = try self.requireStream();
        try self.setDevice();

        try checkCuda(nccl.cudaStreamSynchronize(stream), "cudaStreamSynchronize", error.CudaSynchronizeFailed);

        const pending_err = nccl.cudaGetLastError();
        try checkCuda(pending_err, "cudaGetLastError", error.CudaSynchronizeFailed);
    }

    pub fn isRoot(self: *const GPUCoordinator) bool {
        return self.rank == 0;
    }
};

1. The `errdefer` that should destroy `nccl_comm_local` has the wrong lexical scope. It is declared inside the `if (world_size > 1)` block and is canceled when that block exits normally. Consequently, if `cudaStreamCreate` fails afterward, the successfully created NCCL communicator is leaked instead of being destroyed.

2. The failed-initialization path does not abort the NCCL communicator. If stream creation or a later initialization step fails after `ncclCommInitRank` succeeds, merely destroying—or currently leaking—the communicator is insufficient for robust distributed failure handling. Other ranks can remain blocked or later hang because this rank never calls `ncclCommAbort`.

3. The single-rank branch of `doAllReduce` does not call `self.setDevice()` before `cudaMemcpy`. CUDA’s current device can have been changed by another coordinator or external CUDA code since initialization, causing the copy to execute against the wrong device context or fail with an invalid-device-pointer/resource error.

4. The single-rank branch of `doAllReduce` bypasses `requireStream`. It can therefore report success and access CUDA memory after `deinit`, even though the coordinator’s stream and communicator have been destroyed.

5. The single-rank copy uses `cudaMemcpy`, which is not submitted to `self.cuda_stream`. It therefore does not preserve the same stream-ordering semantics as the multi-rank `ncclAllReduce` path. Work queued on the coordinator stream may not be correctly ordered with this copy under all default-stream configurations.

6. The single-rank implementation changes synchronization behavior. The multi-rank operation is enqueued asynchronously on `self.cuda_stream`, while the single-rank fallback uses the synchronous/default-stream `cudaMemcpy` API. Callers therefore receive materially different blocking and ordering behavior depending on `world_size`.

7. The element-size switch in the single-rank branch is incorrect for most NCCL data types. Every unlisted type is treated as four bytes:
   - `ncclInt8` and `ncclUint8` require one byte.
   - `ncclFloat64`, `ncclInt64`, and `ncclUint64` require eight bytes.
   - Other two-byte types such as `ncclBfloat16`, when available, require two bytes.
   The private function currently has only float32 public wrappers, but its generic `dtype` parameter and explicit float16 case make the fallback incorrect as soon as another datatype wrapper is added.

8. `copyHostToDevice` does not verify that `size` is no larger than the source slice. Passing a slice with fewer than `size` bytes causes an out-of-bounds host read.

9. `copyHostToDevice` does not verify that `size` fits the destination allocation. Passing an excessive size causes an out-of-bounds device write.

10. `copyDeviceToHost` does not verify that `size` is no larger than the destination slice. Passing a slice with insufficient capacity causes an out-of-bounds host write and memory corruption.

11. `copyDeviceToHost` does not verify that `size` fits the source device allocation. Passing an excessive size causes an out-of-bounds device read.

12. Slice bounds are measured in elements, but the copy APIs accept `size` in bytes and discard all slice-length information in `opaquePtrFrom` and `constOpaquePtrFrom`. Even when the caller supplies slices, the implementation gives up the information needed to validate byte capacity as `value.len * @sizeOf(element_type)`.

13. The slice-capacity calculation that would be needed for safe copies is absent, including overflow checking for `value.len * @sizeOf(element_type)`. As written, no meaningful bound validation is performed at all.

14. `doMemcpy` requires a CUDA stream but never uses that stream. The actual operation is performed by `cudaMemcpy`, not `cudaMemcpyAsync(..., stream)`. This makes the stream requirement operationally meaningless and prevents copies solely because the stream is absent even though the selected API does not consume it.

15. Using synchronous `cudaMemcpy` in both public copy methods unnecessarily blocks or synchronizes compared with a stream-based asynchronous copy. This defeats much of the purpose of maintaining a dedicated CUDA stream and prevents normal overlap of communication, computation, and memory transfer.

16. `allocDeviceMemory` does not verify that the coordinator is still initialized. After `deinit`, it continues to allocate memory successfully because it only calls `setDevice`. This is inconsistent with copy, synchronization, and multi-rank collective methods, which reject the deinitialized state.

17. `freeDeviceMemory` likewise remains callable after `deinit`, while other resource-dependent methods reject that state. The object has no explicit lifecycle state, resulting in inconsistent post-destruction behavior across its public API.

18. If `setDevice` fails in `freeDeviceMemory`, the function silently abandons the allocation after printing a message. Because the function returns `void`, the caller cannot detect the failure, retry the free, or reliably know that the device allocation leaked.

19. If `cudaFree` fails, `freeDeviceMemory` only logs the error and provides no failure result to the caller. The caller can incorrectly assume that the allocation was released.

20. `deinit` continues with stream and communicator operations even if `cudaSetDevice(self.device_id)` fails. Those operations can consequently run with the wrong current device and fail, leak resources, or interact with an unrelated device context.

21. `deinit` clears `self.nccl_comm` even when `ncclCommFinalize` or `ncclCommDestroy` fails. This loses the only stored handle and makes cleanup impossible to retry, potentially leaking the communicator permanently.

22. `deinit` clears `self.cuda_stream` even when `cudaStreamDestroy` fails. This similarly loses the handle and prevents cleanup from being retried.

23. `deinit` calls `ncclCommDestroy` unconditionally after a failed `ncclCommFinalize`. A finalize failure can indicate an unhealthy or asynchronously failed communicator, for which abort handling may be required instead of proceeding as though normal finalization succeeded.

24. Asynchronous NCCL errors are never queried with `ncclCommGetAsyncError`. `ncclAllReduce` can return success when the operation has merely been enqueued and then fail asynchronously. `synchronize` checks only CUDA errors, so NCCL-specific asynchronous failures can be missed, misreported, or allowed to leave the communicator unusable.

25. The cleanup path has no handling for an asynchronously failed NCCL communicator. Calling stream synchronization or normal finalization on such a communicator can block indefinitely; a detected asynchronous NCCL failure should lead to communicator abortion rather than unconditional normal cleanup.

26. `synchronize` maps every failure from both `cudaStreamSynchronize` and `cudaGetLastError` to `error.CudaSynchronizeFailed`. This discards whether the failure came from stream synchronization or from a pending CUDA runtime error, preventing callers from distinguishing the two failure classes.

27. `cudaGetLastError` consumes and clears the calling thread’s CUDA last-error state. `synchronize` therefore mutates global/thread-local CUDA diagnostic state and can consume an error originating from unrelated CUDA code executed on the same thread.

28. Conversely, `cudaGetLastError` can report a stale error produced by unrelated earlier CUDA work. The method then incorrectly attributes that error to this coordinator’s synchronization operation.

29. `checkCuda` and `checkNccl` accept `fail_error: anyerror`, which broadens their effective error sets to `anyerror`. This prevents Zig from preserving precise inferred error sets through these helpers and weakens compile-time error-set checking for every caller.

30. The `rank > maxInt(c_int)` check is unreachable after the preceding checks. Since `rank < world_size` and `world_size <= maxInt(c_int)`, `rank` cannot exceed `maxInt(c_int)`. The check is dead duplicated validation.

31. The `device_id_usize > maxInt(i32)` check is redundant on the supported CUDA ABI. `device_count` is a positive `c_int`, `local_rank < device_count`, and CUDA’s `c_int` device ordinal is 32-bit, so `local_rank` is already bounded by `maxInt(i32)`.

32. `const device_id_usize: usize = local_rank;` is a redundant alias that adds no conversion, validation, or semantic distinction.

33. `doAllReduce` does not verify buffer capacity for `count` elements. An excessive count causes NCCL, or the single-rank CUDA copy, to read and write beyond the supplied device allocations.

34. Zero-count collective calls return before validating coordinator state. A deinitialized or otherwise invalid coordinator therefore reports success for a zero-count operation, while the same call with a nonzero count fails. This makes lifecycle validation dependent on data size.

35. Zero-size copy calls likewise return before validating stream and coordinator state. A copy on a deinitialized coordinator reports success when `size == 0` but fails when `size != 0`, producing inconsistent state semantics.

36. The all-reduce API accepts only opaque pointers, so it cannot verify that the pointers refer to device memory on `self.device_id`. A pointer belonging to another device or host memory reaches NCCL/CUDA unchecked and fails later with a less precise runtime error.

37. The copy APIs do not validate that source and destination memory spaces match the requested copy direction. Host-to-device and device-to-host operations can be called with pointers of the wrong memory kind, with failure deferred entirely to CUDA.

38. `opaquePtrFrom` and `constOpaquePtrFrom` accept every `.one` pointer without validating the pointee’s usable byte extent. This includes pointers to zero-length arrays or objects smaller than the requested transfer, allowing the copy routines to overrun them.

39. The public memory-allocation API returns an untyped `*anyopaque` without retaining the allocation size. Because the coordinator stores no allocation metadata, its own copy and collective methods cannot validate ranges even for memory allocated through `allocDeviceMemory`.

40. Cleanup errors are only printed to `std.debug` and are not accumulated or exposed through coordinator state. After `deinit`, the caller cannot determine whether communicator finalization, communicator destruction, stream synchronization, or stream destruction actually succeeded.

1. `constOpaquePtrFrom` is declared as returning an error union (`!*const anyopaque`) but the `.one` branch never returns an error; when called with a single pointer the function can never fail, yet all call sites are forced to use `try`. In the `.one` case the inferred error set only contains `EmptyBuffer` from the slice branch — the error set is non-empty but unreachable for pointer arguments, forcing spurious error handling.

2. `constOpaquePtrFrom`: `@ptrCast(value)` on a single-item pointer to a *non-const* pointee is allowed, but casting a `*const T` to `*const anyopaque` and a `*T` to `*const anyopaque` both silently succeed — the function silently accepts mutable pointers and discards mutability, which is fine, but it also silently accepts `*const` slices/pointers of zero-sized types (`*const void`, `*const u0`), producing a pointer that is not a valid device/host address for `cudaMemcpy`. No element-size validation exists.

3. `constOpaquePtrFrom`: `@ptrCast(&value[0])` on a slice takes the address of the first element but the function loses the length entirely. Callers pass an explicit `size` byte count that is never validated against `value.len * @sizeOf(elem)`, so any mismatch causes an out-of-bounds host read/write in `cudaMemcpy` with no diagnostic.

4. `constOpaquePtrFrom`: for a slice, `&value[0]` is evaluated after the `len == 0` check, but `value` is a by-value copy of the slice; this is correct in Zig, however `@ptrCast(&value[0])` returns a pointer whose alignment attribute is derived from the element type — casting to `*const anyopaque` discards alignment info, so downstream code cannot detect misaligned buffers. No alignment validation is performed anywhere.

5. `constOpaquePtrFrom`: `switch (@typeInfo(T))` uses lowercase field names (`.pointer`, `.one`, `.slice`, `.many`, `.c`) which only compile on Zig 0.14+/0.15 master. If the project targets Zig 0.13 or earlier (`.Pointer`, `.One`, `.Slice`, `.Many`, `.C`), this is a hard compile error. There is no version guard anywhere in the file, and the mixed use of `nccl.cudaMemcpyKind.cudaMemcpyHostToDevice` (namespaced enum literal) suggests inconsistent API-era assumptions.

6. `constOpaquePtrFrom`: the `.pointer` case does not handle `ptr_info.is_allowzero`, so a pointer created from address 0 is accepted and passed to CUDA, which will return an error only at runtime.

7. `constOpaquePtrFrom`: the switch on `ptr_info.size` has no `else` branch. This is exhaustive today, but if a new pointer size kind is ever added the code breaks; more importantly, the `.many`/`.c` arm uses `@compileError` inside a *runtime* switch expression on a comptime-known value — this is legal but the entire switch is evaluated at comptime for the tag, so it works; however combining `@compileError` arms with runtime-error arms in the same switch makes the inferred error set of the function dependent on which arm is instantiated, producing inconsistent error sets across instantiations and making `try` at call sites behave differently per type.

8. `opaquePtrFrom`: identical structural duplication of `constOpaquePtrFrom` — the entire body is duplicated logic with only the const check and return type differing. This is unmaintainable duplicated logic; a single generic helper parameterized on constness should exist.

9. `opaquePtrFrom` `.one` branch: `if (ptr_info.is_const) @compileError(...)` is placed inside a `blk:` block whose other statement is a `break :blk`. Because `ptr_info.is_const` is comptime-known, the `if` is comptime-evaluated and this works, but the `blk:` label is unnecessary and the `@compileError` path means the block has no `break` on that path — relying on `@compileError` terminating analysis. This is fragile style and inconsistent with the `.slice` arm which does the same thing but then also has a runtime `return error.EmptyBuffer` inside the same block, mixing comptime aborts and runtime returns in one block expression.

10. `opaquePtrFrom` `.slice` branch: a `[]const u8` slice triggers `@compileError`, but the check `ptr_info.is_const` on a slice refers to the constness of the *element* pointer, which is correct; however there is no check for `ptr_info.sentinel`, so a sentinel-terminated slice `[:0]u8` is accepted and `&value[0]` is used while the sentinel is not counted in `len` — a size mismatch source that is never validated.

11. `opaquePtrFrom`: returns `!*anyopaque` but for the `.one` mutable-pointer case cannot fail; same spurious-error-union problem as #1.

12. `checkCuda`: takes `fail_error: anyerror` as a *runtime* parameter. This defeats Zig's error-set inference — the inferred error set of every caller becomes `anyerror`, destroying exhaustive error handling at all call sites and preventing the compiler from proving which errors can occur. It should be a comptime parameter or a comptime-known error set.

13. `checkCuda`: compares `err != .cudaSuccess`. If `nccl.CudaError` is a non-exhaustive enum (`enum(c_int) { ..., _ }`), an unknown driver error code still compares unequal and is reported, which is fine, but if `CudaError` is declared as a plain `c_int` typedef this fails to compile. The code assumes an enum without any guarantee.

14. `checkCuda`: `nccl.cudaGetErrorString(err)` is printed with `{s}`. If the binding returns `[*c]const u8` (the natural C mapping), `{s}` on a `[*c]const u8` is a compile error in modern Zig (`std.fmt` requires a slice or a sentinel-terminated many-pointer). If it returns `[*:0]const u8`, `{s}` works. The code silently depends on the binding wrapping the return value; nothing in this file guarantees it. Additionally, if `cudaGetErrorString` returns null (possible for out-of-range codes), `{s}` dereferences a null pointer → crash.

15. `checkCuda`/`checkNccl`/`logCudaFailure`/`logNcclFailure`: all four are near-identical duplicated logic differing only in the enum type, success sentinel, error-string function, and message prefix. Four copies of the same six lines.

