```zig
const std = @import("std");
const nccl = @import("nccl_bindings.zig");

pub const DeviceBuffer = struct {
    ptr: *anyopaque,
    size: usize,
};

const PtrInfo = struct {
    ptr: *anyopaque,
    size: usize,
};

fn getPtrAndSize(value: anytype, comptime require_mutable: bool) !PtrInfo {
    const T = @TypeOf(value);
    if (T == DeviceBuffer) {
        if (@intFromPtr(value.ptr) == 0 and value.size > 0) return error.NullPointer;
        return PtrInfo{ .ptr = value.ptr, .size = value.size };
    }
    const type_info = @typeInfo(T);
    switch (type_info) {
        .Pointer => |ptr_info| {
            if (ptr_info.is_const and require_mutable) {
                @compileError("Expected mutable pointer/slice, got " ++ @typeName(T));
            }
            if (@sizeOf(ptr_info.child) == 0) {
                @compileError("Pointer to zero-sized type is invalid for CUDA: " ++ @typeName(T));
            }
            switch (ptr_info.size) {
                .One => {
                    const ptr_addr = @intFromPtr(value);
                    if (ptr_addr == 0) return error.NullPointer;
                    return PtrInfo{
                        .ptr = @as(*anyopaque, @ptrFromInt(ptr_addr)),
                        .size = @sizeOf(ptr_info.child),
                    };
                },
                .Slice => {
                    if (value.len == 0) {
                        return PtrInfo{ .ptr = undefined, .size = 0 };
                    }
                    const byte_size = try std.math.mul(usize, value.len, @sizeOf(ptr_info.child));
                    const ptr_addr = @intFromPtr(value.ptr);
                    if (ptr_addr == 0) return error.NullPointer;
                    return PtrInfo{
                        .ptr = @as(*anyopaque, @ptrFromInt(ptr_addr)),
                        .size = byte_size,
                    };
                },
                else => {
                    @compileError("Expected single pointer or slice, got " ++ @typeName(T));
                }
            }
        },
        else => {
            @compileError("Expected pointer or slice, got " ++ @typeName(T));
        }
    }
}

fn checkCudaError(err: nccl.CudaError, comptime fail_error: anyerror) !void {
    if (@as(c_int, @intCast(err)) != @as(c_int, @intCast(nccl.cudaSuccess))) {
        const err_ptr = nccl.cudaGetErrorString(err);
        const err_str = if (err_ptr != null) std.mem.span(err_ptr) else "Unknown";
        std.log.err("CUDA error: {s}", .{err_str});
        return fail_error;
    }
}

fn checkNcclError(err: nccl.ncclResult_t, comptime fail_error: anyerror) !void {
    const err_int = @as(c_int, @intCast(err));
    if (err_int != @as(c_int, @intCast(nccl.ncclSuccess)) and err_int != @as(c_int, @intCast(nccl.ncclInProgress))) {
        const err_ptr = nccl.ncclGetErrorString(err);
        const err_str = if (err_ptr != null) std.mem.span(err_ptr) else "Unknown";
        std.log.err("NCCL error: {s}", .{err_str});
        return fail_error;
    }
}

fn validateDevicePointer(ptr: *const anyopaque, expected_device: i32) !void {
    if (@intFromPtr(ptr) == 0) return;
    var attrs: nccl.cudaPointerAttributes = undefined;
    const err = nccl.cudaPointerGetAttributes(&attrs, ptr);
    if (@as(c_int, @intCast(err)) != @as(c_int, @intCast(nccl.cudaSuccess))) {
        _ = nccl.cudaGetLastError();
        return error.NotDevicePointer;
    }
    if (@hasField(nccl.cudaPointerAttributes, "type")) {
        if (attrs.type != nccl.cudaMemoryTypeDevice) return error.NotDevicePointer;
    } else if (@hasField(nccl.cudaPointerAttributes, "memoryType")) {
        if (attrs.memoryType != nccl.cudaMemoryTypeDevice) return error.NotDevicePointer;
    }
    if (attrs.device != expected_device) return error.WrongDevice;
}

fn validateHostPointer(ptr: *const anyopaque) !void {
    if (@intFromPtr(ptr) == 0) return;
    var attrs: nccl.cudaPointerAttributes = undefined;
    const err = nccl.cudaPointerGetAttributes(&attrs, ptr);
    if (@as(c_int, @intCast(err)) == @as(c_int, @intCast(nccl.cudaSuccess))) {
        if (@hasField(nccl.cudaPointerAttributes, "type")) {
            if (attrs.type == nccl.cudaMemoryTypeDevice) return error.NotHostPointer;
        } else if (@hasField(nccl.cudaPointerAttributes, "memoryType")) {
            if (attrs.memoryType == nccl.cudaMemoryTypeDevice) return error.NotHostPointer;
        }
    } else {
        _ = nccl.cudaGetLastError();
    }
}

pub const GPUCoordinator = struct {
    world_size: usize,
    rank: usize,
    device_id: i32,
    nccl_comm: ?*nccl.ncclComm,
    cuda_stream: ?*anyopaque,
    is_active: bool,

    pub fn init(world_size: usize, rank: usize, local_rank: usize, nccl_id: nccl.ncclUniqueId) !GPUCoordinator {
        if (world_size == 0) return error.InvalidWorldSize;
        if (world_size > std.math.maxInt(c_int)) return error.WorldSizeTooLarge;
        if (rank >= world_size) return error.InvalidRank;
        if (local_rank > rank) return error.InvalidLocalRank;

        var is_all_zero = true;
        const nccl_id_bytes = @as([*]const u8, @ptrCast(&nccl_id));
        for (0..@sizeOf(nccl.ncclUniqueId)) |i| {
            if (nccl_id_bytes[i] != 0) {
                is_all_zero = false;
                break;
            }
        }
        if (is_all_zero) return error.InvalidNcclId;

        var device_count: c_int = 0;
        try checkCudaError(nccl.cudaGetDeviceCount(&device_count), error.CudaGetDeviceCountFailed);
        if (device_count <= 0) return error.InsufficientGPUs;

        if (local_rank >= @as(usize, @intCast(device_count))) return error.LocalRankExceedsDeviceCount;
        const device_id: i32 = @intCast(local_rank);

        var prev_device: c_int = 0;
        try checkCudaError(nccl.cudaGetDevice(&prev_device), error.CudaGetDeviceFailed);
        errdefer _ = nccl.cudaSetDevice(prev_device);

        try checkCudaError(nccl.cudaSetDevice(device_id), error.CudaSetDeviceFailed);

        var nccl_comm_opt: ?*nccl.ncclComm = null;
        if (world_size > 1) {
            var nccl_comm_local: ?*nccl.ncclComm = null;
            try checkNcclError(
                nccl.ncclCommInitRank(&nccl_comm_local, @as(c_int, @intCast(world_size)), nccl_id, @as(c_int, @intCast(rank))),
                error.NCCLCommInitFailed,
            );
            if (nccl_comm_local == null) return error.NCCLCommInitFailed;
            nccl_comm_opt = nccl_comm_local;
        }

        errdefer if (nccl_comm_opt) |comm| {
            _ = nccl.ncclCommAbort(comm);
        };

        try checkCudaError(nccl.cudaSetDevice(device_id), error.CudaSetDeviceFailed);

        var cuda_stream_local: ?*anyopaque = null;
        try checkCudaError(nccl.cudaStreamCreate(&cuda_stream_local), error.CudaStreamCreateFailed);
        if (cuda_stream_local == null) return error.CudaStreamCreateFailed;

        _ = nccl.cudaSetDevice(prev_device);

        return GPUCoordinator{
            .world_size = world_size,
            .rank = rank,
            .device_id = device_id,
            .nccl_comm = nccl_comm_opt,
            .cuda_stream = cuda_stream_local,
            .is_active = true,
        };
    }

    pub fn deinit(self: *GPUCoordinator) !void {
        if (!self.is_active) return error.AlreadyDeinitialized;
        self.is_active = false;

        var prev_device: c_int = 0;
        try checkCudaError(nccl.cudaGetDevice(&prev_device), error.CudaGetDeviceFailed);
        defer _ = nccl.cudaSetDevice(prev_device);

        try self.setDevice();

        if (self.cuda_stream) |stream| {
            try checkCudaError(nccl.cudaStreamSynchronize(stream), error.CudaSynchronizeFailed);
        }

        if (self.nccl_comm) |comm| {
            var async_err: nccl.ncclResult_t = .ncclSuccess;
            _ = nccl.ncclCommGetAsyncError(comm, &async_err);
            if (@as(c_int, @intCast(async_err)) != @as(c_int, @intCast(nccl.ncclSuccess))) {
                _ = nccl.ncclCommAbort(comm);
                self.nccl_comm = null;
            } else {
                var abort = false;
                if (@hasDecl(nccl, "ncclCommFinalize")) {
                    const fin_err = nccl.ncclCommFinalize(comm);
                    const fin_int = @as(c_int, @intCast(fin_err));
                    if (fin_int != @as(c_int, @intCast(nccl.ncclSuccess)) and fin_int != @as(c_int, @intCast(nccl.ncclInProgress))) {
                        abort = true;
                    }
                }
                if (abort) {
                    _ = nccl.ncclCommAbort(comm);
                    self.nccl_comm = null;
                } else {
                    if (self.cuda_stream) |s| {
                        _ = nccl.cudaStreamSynchronize(s);
                    }
                    try checkNcclError(nccl.ncclCommDestroy(comm), error.NCCLCommDestroyFailed);
                    self.nccl_comm = null;
                }
            }
        }

        if (self.cuda_stream) |stream| {
            try checkCudaError(nccl.cudaStreamDestroy(stream), error.CudaStreamDestroyFailed);
            self.cuda_stream = null;
        }
    }

    fn checkActive(self: *const GPUCoordinator) !void {
        if (!self.is_active) return error.CoordinatorNotInitialized;
    }

    fn setDevice(self: *const GPUCoordinator) !void {
        try checkCudaError(nccl.cudaSetDevice(self.device_id), error.CudaSetDeviceFailed);
    }

    fn requireComm(self: *const GPUCoordinator) !*nccl.ncclComm {
        try self.checkActive();
        if (self.nccl_comm) |comm| return comm;
        return error.NoCommunicator;
    }

    fn requireStream(self: *const GPUCoordinator) !*anyopaque {
        try self.checkActive();
        if (self.cuda_stream) |stream| return stream;
        return error.NoStream;
    }

    pub fn allocDeviceMemory(self: *const GPUCoordinator, size: usize) !DeviceBuffer {
        try self.checkActive();
        if (size == 0) return error.InvalidAllocationSize;

        var prev_device: c_int = 0;
        try checkCudaError(nccl.cudaGetDevice(&prev_device), error.CudaGetDeviceFailed);
        defer _ = nccl.cudaSetDevice(prev_device);

        try self.setDevice();

        var dev_ptr: ?*anyopaque = null;
        try checkCudaError(nccl.cudaMalloc(&dev_ptr, size), error.CudaMallocFailed);
        if (dev_ptr) |p| {
            return DeviceBuffer{ .ptr = p, .size = size };
        }
        return error.CudaMallocFailed;
    }

    pub fn freeDeviceMemory(self: *const GPUCoordinator, buf: DeviceBuffer) !void {
        try self.checkActive();
        if (@intFromPtr(buf.ptr) == 0) return;

        var prev_device: c_int = 0;
        try checkCudaError(nccl.cudaGetDevice(&prev_device), error.CudaGetDeviceFailed);
        defer _ = nccl.cudaSetDevice(prev_device);

        try self.setDevice();
        try checkCudaError(nccl.cudaFree(buf.ptr), error.CudaFreeFailed);
    }

    fn doMemcpyAsync(
        self: *const GPUCoordinator,
        dst_ptr: *anyopaque,
        src_ptr: *const anyopaque,
        size: usize,
        kind: nccl.cudaMemcpyKind,
    ) !void {
        const stream = try self.requireStream();
        var prev_device: c_int = 0;
        try checkCudaError(nccl.cudaGetDevice(&prev_device), error.CudaGetDeviceFailed);
        defer _ = nccl.cudaSetDevice(prev_device);

        try self.setDevice();
        try checkCudaError(nccl.cudaMemcpyAsync(dst_ptr, src_ptr, size, kind, stream), error.CudaMemcpyFailed);
    }

    pub fn copyHostToDevice(self: *const GPUCoordinator, dst: anytype, src: anytype, size: usize) !void {
        try self.checkActive();
        if (size == 0) {
            _ = try self.requireStream();
            return;
        }

        const dst_info = try getPtrAndSize(dst, true);
        const src_info = try getPtrAndSize(src, false);

        if (size > dst_info.size) return error.DestinationTooSmall;
        if (size > src_info.size) return error.SourceTooSmall;

        try validateDevicePointer(dst_info.ptr, self.device_id);
        try validateHostPointer(src_info.ptr);

        try self.doMemcpyAsync(dst_info.ptr, src_info.ptr, size, nccl.cudaMemcpyKind.cudaMemcpyHostToDevice);
    }

    pub fn copyDeviceToHost(self: *const GPUCoordinator, dst: anytype, src: anytype, size: usize) !void {
        try self.checkActive();
        if (size == 0) {
            _ = try self.requireStream();
            return;
        }

        const dst_info = try getPtrAndSize(dst, true);
        const src_info = try getPtrAndSize(src, false);

        if (size > dst_info.size) return error.DestinationTooSmall;
        if (size > src_info.size) return error.SourceTooSmall;

        try validateHostPointer(dst_info.ptr);
        try validateDevicePointer(src_info.ptr, self.device_id);

        try self.doMemcpyAsync(dst_info.ptr, src_info.ptr, size, nccl.cudaMemcpyKind.cudaMemcpyDeviceToHost);
    }

    fn doAllReduce(
        self: *const GPUCoordinator,
        send_buf: anytype,
        recv_buf: anytype,
        count: usize,
        dtype: nccl.ncclDataType_t,
        op: nccl.ncclRedOp_t,
    ) !void {
        try self.checkActive();
        if (count == 0) {
            _ = try self.requireStream();
            return;
        }

        const send_info = try getPtrAndSize(send_buf, false);
        const recv_info = try getPtrAndSize(recv_buf, true);

        const dtype_int = @as(c_int, @intCast(dtype));
        const elem_bytes: usize = if (dtype_int == @as(c_int, @intCast(nccl.ncclDataType_t.ncclInt8)) or dtype_int == @as(c_int, @intCast(nccl.ncclDataType_t.ncclUint8))) 1
        else if (dtype_int == @as(c_int, @intCast(nccl.ncclDataType_t.ncclFloat16))) 2
        else if (dtype_int == @as(c_int, @intCast(nccl.ncclDataType_t.ncclInt64)) or dtype_int == @as(c_int, @intCast(nccl.ncclDataType_t.ncclUint64)) or dtype_int == @as(c_int, @intCast(nccl.ncclDataType_t.ncclFloat64))) 8
        else if (@hasDecl(nccl.ncclDataType_t, "ncclBfloat16") and dtype_int == @as(c_int, @intCast(nccl.ncclDataType_t.ncclBfloat16))) 2
        else 4;

        const req_bytes = try std.math.mul(usize, count, elem_bytes);
        if (req_bytes > send_info.size) return error.SourceTooSmall;
        if (req_bytes > recv_info.size) return error.DestinationTooSmall;

        try validateDevicePointer(send_info.ptr, self.device_id);
        try validateDevicePointer(recv_info.ptr, self.device_id);

        if (self.world_size == 1) {
            if (send_info.ptr != recv_info.ptr) {
                try self.doMemcpyAsync(recv_info.ptr, send_info.ptr, req_bytes, nccl.cudaMemcpyKind.cudaMemcpyDeviceToDevice);
            }
            return;
        }

        const comm = try self.requireComm();
        const stream = try self.requireStream();

        var prev_device: c_int = 0;
        try checkCudaError(nccl.cudaGetDevice(&prev_device), error.CudaGetDeviceFailed);
        defer _ = nccl.cudaSetDevice(prev_device);

        try self.setDevice();

        try checkNcclError(
            nccl.ncclAllReduce(send_info.ptr, recv_info.ptr, count, dtype, op, comm, stream),
            error.NCCLAllReduceFailed,
        );
    }

    pub fn allReduceFloat32(self: *const GPUCoordinator, send_buf: anytype, recv_buf: anytype, count: usize) !void {
        try self.doAllReduce(send_buf, recv_buf, count, .ncclFloat32, .ncclSum);
    }

    pub fn allReduceFloat32Max(self: *const GPUCoordinator, send_buf: anytype, recv_buf: anytype, count: usize) !void {
        try self.doAllReduce(send_buf, recv_buf, count, .ncclFloat32, .ncclMax);
    }

    pub fn synchronize(self: *const GPUCoordinator) !void {
        const stream = try self.requireStream();

        var prev_device: c_int = 0;
        try checkCudaError(nccl.cudaGetDevice(&prev_device), error.CudaGetDeviceFailed);
        defer _ = nccl.cudaSetDevice(prev_device);

        try self.setDevice();
        try checkCudaError(nccl.cudaStreamSynchronize(stream), error.CudaSynchronizeFailed);

        if (self.nccl_comm) |comm| {
            var async_err: nccl.ncclResult_t = .ncclSuccess;
            _ = nccl.ncclCommGetAsyncError(comm, &async_err);
            try checkNcclError(async_err, error.NCCLAsyncError);
        }
    }

    pub fn isRoot(self: *const GPUCoordinator) bool {
        return self.rank == 0;
    }
};
